extends Sprite2D

@export var speed: float = 250.0

func _process(delta: float) -> void:
	# Legge l'input orizzontale e verticale restituendo un vettore bilanciato
	var input_direction: Vector2 = Input.get_vector("move_left", "move_right", "move_up", "move_down")

	# Moltiplica la direzione normalizzata per la velocita desiderata
	var velocity: Vector2 = input_direction * speed

	# Applica lo spostamento scalato con delta alla posizione del nodo
	position += velocity * delta

extends Sprite2D

@export var speed: float = 120.0
@export var target_position: Vector2 = Vector2(300.0, 200.0)

func _process(delta: float) -> void:
	# Calcola la direzione verso la destinazione
	var direction: Vector2 = global_position.direction_to(target_position)

	# Ruota il nodo solo se non ha ancora raggiunto la destinazione
	if direction != Vector2.ZERO:
		rotation = direction.angle()

	# Fa avanzare la posizione senza superare il punto finale
	global_position = global_position.move_toward(target_position, speed * delta)

