func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main_scene", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var guard := find_by_name(main, "Guard")
	if not check("guard_node", guard != null, "Nella scena deve essere presente un nodo chiamato Guard"):
		return

	if not check("has_dir", has_function(guard, "get_direction_to_target"), "Lo script di Guard deve contenere la funzione get_direction_to_target(target)"):
		return
	if not check("has_step", has_function(guard, "step_toward"), "Lo script di Guard deve contenere la funzione step_toward(target, delta_distance)"):
		return

	# Controllo get_direction_to_target verso il basso
	guard.global_position = Vector2(100.0, 100.0)
	var dir_down = call_if_exists(guard, "get_direction_to_target", [Vector2(100.0, 300.0)], Vector2.ZERO)
	if check("dir_type", dir_down is Vector2, "get_direction_to_target deve restituire un Vector2"):
		var v_dir: Vector2 = dir_down as Vector2
		check("dir_val", absf(v_dir.x) < 0.01 and absf(v_dir.y - 1.0) < 0.01, "Verso un punto situato in basso (100, 300) la direzione deve essere (0, 1) (misurata: %.2f, %.2f)" % [v_dir.x, v_dir.y])

	# Controllo step_toward con passo parziale
	guard.global_position = Vector2(100.0, 100.0)
	var step_pos = call_if_exists(guard, "step_toward", [Vector2(100.0, 200.0), 30.0], Vector2.ZERO)
	if check("step_type", step_pos is Vector2, "step_toward deve restituire un Vector2"):
		var v_step: Vector2 = step_pos as Vector2
		check("step_val", absf(v_step.x - 100.0) < 0.1 and absf(v_step.y - 130.0) < 0.1, "Avanzando di 30 pixel verso (100, 200) la nuova posizione deve essere (100, 130) (misurata: %.1f, %.1f)" % [v_step.x, v_step.y])

	# Controllo step_toward che non oltrepassa il bersaglio
	var clamp_pos = call_if_exists(guard, "step_toward", [Vector2(150.0, 100.0), 200.0], Vector2.ZERO)
	if clamp_pos is Vector2:
		var v_clamp: Vector2 = clamp_pos as Vector2
		check("step_clamp", absf(v_clamp.x - 150.0) < 0.1 and absf(v_clamp.y - 100.0) < 0.1, "Se il passo supera la distanza rimanente, step_toward deve arrestarsi con precisione su target (150, 100)")

	# Controllo rotazione e spostamento continuo in _process
	guard.global_position = Vector2(100.0, 100.0)
	guard.set("target_position", Vector2(100.0, 300.0))
	await wait_physics_frames(10)
	check("rotation_down", absf(guard.rotation - PI * 0.5) < 0.1, "Puntando verso il basso la guardia deve ruotare di circa 1.57 radianti (misurata: %.2f)" % guard.rotation)
	check("moved_down", guard.global_position.y > 105.0, "Nel tempo la guardia deve muoversi verso target_position (partita da 100.0, arrivata a y: %.1f)" % guard.global_position.y)

